-- Catalog-only audit. READ ONLY. Do not invoke business RPCs here.
BEGIN READ ONLY;
SELECT p.proname, pg_get_function_identity_arguments(p.oid) arguments, p.prosecdef security_definer, p.proconfig, has_function_privilege('authenticated',p.oid,'EXECUTE') authenticated_execute, has_function_privilege('anon',p.oid,'EXECUTE') anon_execute, pg_get_functiondef(p.oid) definition FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='public' AND p.proname IN ('atry_access','atry_bookings','atry_business','atry_catalog','atry_create_booking','atry_create_incident','atry_create_recurring','atry_customer_history','atry_customers','atry_dashboard','atry_end_recurring','atry_entitlements','atry_insights','atry_mail_jobs','atry_notification_preferences','atry_recurring','atry_rules','atry_save_appearance','atry_save_business','atry_save_customer','atry_save_notification_preferences','atry_save_rule','atry_save_service','atry_save_staff','atry_save_week','atry_smartslots','atry_statistics','atry_update_booking','atry_update_waitlist','atry_visit','atry_visit_availability','atry_visit_command','atry_waitlist','atry_whatsapp');
SELECT tablename,policyname,roles,cmd,qual,with_check FROM pg_policies WHERE schemaname='public';
SELECT c.relname,c.relrowsecurity,pg_get_constraintdef(k.oid) constraint_definition FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace LEFT JOIN pg_constraint k ON k.conrelid=c.oid WHERE n.nspname='public' AND c.relkind='r';
ROLLBACK;
